// Prepare normal results notification for patient
const data = $input.first().json;
const patient = data.patientData.patient;
const labOrder = data.patientData.labOrder;
const normalTests = data.patientData.normalTests;

// Build patient-friendly test summary
const testSummary = normalTests.map(test => 
  `• ${test.testName}: ${test.value} ${test.referenceRange?.units || ''} (normal)`
).join('\n');

// Generate secure link to view full results
// In production, this would be a time-limited token to patient portal
const secureLink = process.env.PATIENT_PORTAL_URL || 'https://portal.drjennifer.com/results';
const resultId = `LAB-${patient.id}-${Date.now()}`;
const fullLink = `${secureLink}?id=${resultId}&token=${Buffer.from(resultId).toString('base64')}`;

// Build SMS message
const smsMessage = `Hi ${patient.name.split(' ')[0]}, your lab results from ${labOrder.collectionDate || 'recent visit'} are ready.

✅ Everything looks normal!

View detailed results: ${fullLink}

Next steps: None needed. Continue current medications.

Questions? Reply to this message or call us: ${process.env.OFFICE_PHONE || '(555) 555-1234'}`;

// Build email message (HTML)
const emailSubject = `Your Lab Results Are Ready - All Normal`;
const emailBody = `<html>
<body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
  <div style="max-width: 600px; margin: 0 auto; padding: 20px;">
    <h2 style="color: #2c5282;">Lab Results: All Normal ✅</h2>

    <p>Hi ${patient.name},</p>

    <p>Your lab results from ${labOrder.collectionDate || 'your recent visit'} are ready.</p>

    <div style="background: #d4edda; border-left: 4px solid #28a745; padding: 15px; margin: 20px 0;">
      <strong style="color: #155724;">Good news! All your test results are within normal range.</strong>
    </div>

    <h3>Test Summary:</h3>
    <ul>
${normalTests.map(test => 
  `      <li>${test.testName}: ${test.value} ${test.referenceRange?.units || ''} <span style="color: #28a745;">(normal range: ${test.referenceRange?.normalMin}-${test.referenceRange?.normalMax})</span></li>`
).join('\n')}
    </ul>

    <h3>Next Steps:</h3>
    <p>No action needed. Continue your current medications as prescribed.</p>

    <p>
      <a href="${fullLink}" style="display: inline-block; background: #2c5282; color: white; padding: 12px 24px; text-decoration: none; border-radius: 5px; margin: 10px 0;">View Full Results</a>
    </p>

    <p style="font-size: 12px; color: #666; margin-top: 30px;">
      <strong>Questions?</strong> Reply to this email or call us at ${process.env.OFFICE_PHONE || '(555) 555-1234'}
    </p>

    <p style="font-size: 11px; color: #999; margin-top: 20px;">
      This message contains confidential medical information. If you received this in error, please delete immediately.
    </p>
  </div>
</body>
</html>`;

return {
  json: {
    patient: patient,
    smsMessage: smsMessage,
    emailSubject: emailSubject,
    emailBody: emailBody,
    secureLink: fullLink,
    resultId: resultId,

    // For logging
    decision: data.decision,
    reasoning: data.reasoning,
    testCount: normalTests.length
  }
};

// Prepare abnormal results for doctor review via Slack
const data = $input.first().json;
const patient = data.patientData.patient;
const labOrder = data.patientData.labOrder;
const abnormalTests = data.patientData.abnormalTests;
const normalTests = data.patientData.normalTests;

const slackMessage = {
  channel: process.env.SLACK_LAB_CHANNEL || '#lab-results',
  text: `⚠️ Abnormal Lab Results - Doctor Review Needed`,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: '⚠️ Abnormal Lab Results - Review Needed'
      }
    },
    {
      type: 'section',
      fields: [
        {
          type: 'mrkdwn',
          text: `*Patient:*\n${patient.name}`
        },
        {
          type: 'mrkdwn',
          text: `*Patient ID:*\n${patient.id}`
        },
        {
          type: 'mrkdwn',
          text: `*Collection Date:*\n${labOrder.collectionDate || 'Unknown'}`
        },
        {
          type: 'mrkdwn',
          text: `*Ordering Provider:*\n${labOrder.orderingProvider}`
        }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*⚠️ Abnormal Values (${abnormalTests.length}):*\n${abnormalTests.map(t => `• ${t.interpretation}`).join('\n')}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*✅ Normal Values (${normalTests.length}):*\n${normalTests.map(t => `• ${t.testName}: ${t.value} ${t.referenceRange?.units || ''}`).join('\n')}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*AI Analysis:*\n${data.reasoning}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Recommended Action:*\n${data.recommendedAction}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*AI Suggested Patient Message:*\n

`
      }
    },
    {
      type: 'divider'
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Patient Contact: ${patient.phone || 'N/A'} | ${patient.email || 'N/A'}`
        }
      ]
    }
  ]
};

return {
  json: {
    slackMessage: slackMessage,

    // Pass through for logging
    patient: patient,
    decision: data.decision,
    reasoning: data.reasoning,
    abnormalCount: abnormalTests.length
  }
};

// Prepare CRITICAL result escalation
const data = $input.first().json;
const patient = data.patientData.patient;
const labOrder = data.patientData.labOrder;
const criticalTests = data.patientData.criticalTests;
const concerningFindings = data.concerningFindings;

// Build urgent SMS to staff
const staffSMS = `🚨🚨🚨 CRITICAL LAB RESULT 🚨🚨🚨

Patient: ${patient.name}
Phone: ${patient.phone || 'N/A'}
Patient ID: ${patient.id}

${criticalTests.map(t => t.interpretation).join('\n')}

IMMEDIATE ACTION REQUIRED
Call patient NOW - ${data.urgencyLevel === 'immediate' ? 'life-threatening emergency' : 'urgent medical attention needed'}

Ordering Provider: ${labOrder.orderingProvider}`;

// Build Slack critical alert
const slackAlert = {
  channel: process.env.SLACK_URGENT_CHANNEL || '#critical-labs',
  text: `🚨 CRITICAL LAB RESULT - IMMEDIATE ACTION REQUIRED`,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: '🚨🚨🚨 CRITICAL LAB RESULT 🚨🚨🚨'
      }
    },
    {
      type: 'section',
      fields: [
        {
          type: 'mrkdwn',
          text: `*Patient:*\n${patient.name}`
        },
        {
          type: 'mrkdwn',
          text: `*Phone:*\n${patient.phone || 'N/A'}`
        },
        {
          type: 'mrkdwn',
          text: `*Patient ID:*\n${patient.id}`
        },
        {
          type: 'mrkdwn',
          text: `*Urgency:*\n${data.urgencyLevel.toUpperCase()}`
        }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*🚨 Critical Values (${criticalTests.length}):*\n${criticalTests.map(t => `• ${t.interpretation}`).join('\n')}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*AI Analysis:*\n${data.reasoning}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Recommended Action:*\n${data.recommendedAction}`
      }
    },
    {
      type: 'divider'
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `⚠️ *IMMEDIATE ACTION: Call patient NOW. This is a life-threatening lab value.*`
        }
      ]
    }
  ]
};

return {
  json: {
    staffSMS: staffSMS,
    slackAlert: slackAlert,

    // For phone call
    doctorPhone: process.env.DOCTOR_ON_CALL_PHONE || process.env.STAFF_ALERT_PHONE,

    // Pass through for logging
    patient: patient,
    decision: data.decision,
    reasoning: data.reasoning,
    criticalCount: criticalTests.length,
    concerningFindings: concerningFindings
  }
};
